head.script:
scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (style 은 createBasicSecret 헬퍼가 지정)
    let properties = {
        ref: 'data:gdl_ref.label',
    };

    // 헬퍼의 초기값 setValue 가 선택된 행의 데이터를 덮어쓰므로 생성 전 선택 행과 데이터를 보관
    let rowIdx = gdl_ref.getRowPosition();
    let isSelected = (rowIdx !== null && rowIdx !== undefined && rowIdx >= 0);
    let orgData = isSelected ? gdl_ref.getCellData(rowIdx, "label") : "";

    let cList = $c.gcm.createCList(properties);
    // secret 은 oneditkeyup 이벤트가 없으므로 onkeyup 으로 wframe 의 commit 검증 핸들러를 호출
    let eList = $c.gcm.createEList(["onkeyup"]);

    await $c.gcm.createBasicSecret(cList, eList);

    if (isSelected) {
        // 선택 행에 기록된 헬퍼 초기값(secret)을 생성 전 데이터로 복원
        gdl_ref.setCellData(rowIdx, "label", orgData);
    }
    else {
        // 미선택 상태: 헬퍼 초기값(secret)을 지워 DataList 바인딩 결과(빈값)만 입력창에 남긴다
        target1.setValue("");
    }
}



// 키 입력 시 wframe(common_M_commit_2) 이 정의한 commit 전/후 비교 핸들러 호출
scwin.target1_onkeyup = function (e) {
    scwin.target1_oneditkeyup(null, e);
}
